// Configuration for the whole run.
const env = (k, dflt) => (typeof $env !== 'undefined' && $env[k] !== undefined && $env[k] !== '' ? $env[k] : dflt);
const flag = (k, dflt) => {
  const v = env(k, null);
  if (v === null) return dflt;
  return /^(1|true|yes|on)$/i.test(String(v));
};

const owners = String(env('COLLECT_010_OWNERS', 'Operator-Syn'))
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);
if (!owners.length) throw new Error('COLLECT_010_OWNERS is empty');

// 0 means the whole history of every repository: no `since` is sent and the commit
// endpoint is paginated to its end. A positive value keeps a rolling window.
const windowDays = Number(env('COLLECT_010_WINDOW_DAYS', 0));
const maxCommitPages = Number(env('COLLECT_010_MAX_COMMIT_PAGES', 50));
// Force a full re-fetch of every repository, ignoring the cached copy. Use after
// changing what is collected, or to rebuild a cache you do not trust.
const forceFull = flag('COLLECT_010_FORCE_FULL_RESYNC', false);
// Stop collecting when this few API calls remain, so a run never dies mid-way with
// every remaining repository erroring. Cached data is preserved for the rest.
const rateReserve = Number(env('COLLECT_010_RATE_RESERVE', 25));
const token = env('COLLECT_010_GITHUB_TOKEN', '');

const headers = { Accept: 'application/vnd.github+json', 'User-Agent': 'mnemora-collector' };
if (token) headers.Authorization = 'Bearer ' + token;

const now = new Date();
const until = now.toISOString();
const since =
  windowDays > 0 ? new Date(now.getTime() - windowDays * 24 * 3600 * 1000).toISOString() : null;

return [
  {
    json: {
      owners,
      since,
      until,
      history: since ? `last ${windowDays} days` : 'full history',
      maxCommitPages,
      forceFull,
      rateReserve,
      headers,
      includeForks: flag('COLLECT_010_INCLUDE_FORKS', true),
      includeArchived: flag('COLLECT_010_INCLUDE_ARCHIVED', true),
    },
  },
];

// Discovers every public repository of each configured owner and brings the cache up
// to date, touching only what actually changed.
//
// Three collection modes per repository, cheapest first:
//   skipped      - pushed_at is unchanged since the cached copy, so nothing is fetched
//   incremental  - new commits only, via `since`, merged into the cached history
//   full         - the whole history, for a repository with no usable cache
//
// A repository whose history was rewritten (force-push) fails the incremental check and
// falls back to a full resync, so ghosts cannot accumulate.
const cfg = $('Build Plan').first().json;
const STATUS_FILE = 'collector-status.json';
const API = 'https://api.github.com';
const httpGet = this.helpers.httpRequest.bind(this.helpers);

// Tracks GitHub's remaining quota from response headers so the run can stop early
// instead of burning the last calls and then failing on every remaining repository.
let budget = null;
async function get(url, qs) {
  const res = await httpGet({
    url,
    qs,
    headers: cfg.headers,
    json: true,
    timeout: 30000,
    returnFullResponse: true,
  });
  const h = res.headers || {};
  const raw = h['x-ratelimit-remaining'] !== undefined ? h['x-ratelimit-remaining'] : h['X-RateLimit-Remaining'];
  if (raw !== undefined && raw !== null && !Number.isNaN(Number(raw))) budget = Number(raw);
  return res.body;
}

// --- previous cache, read from disk by the node before this one -----------------
const existing = {};
for (const item of $input.all()) {
  // The node before this one turns each cache file into plain JSON. Reading the file's
  // binary instead is a trap: n8n 2.x keeps binary payloads in the database and hands a
  // Code node a reference ("database"), not the bytes, so any attempt to decode it in
  // place fails and looks exactly like "no cache exists".
  // Extract From File nests the parsed object under its destination key (json.data),
  // so unwrap it before looking for cache_file.
  const payload = item.json && item.json.data ? item.json.data : item.json;
  const rec = payload && payload.cache_file ? payload : null;
  // The status file is not a repository record; ignore it here.
  if (rec && rec.cache_file !== STATUS_FILE) existing[rec.cache_file] = rec;
}

// --- discovery ----------------------------------------------------------------
const repos = [];
for (const owner of cfg.owners) {
  for (let page = 1; page <= 20; page++) {
    const batch = await get(`${API}/users/${owner}/repos`, { per_page: 100, page, sort: 'full_name' });
    const list = Array.isArray(batch) ? batch : [];
    for (const repo of list) {
      if (repo.visibility !== 'public') continue;
      if (repo.fork && !cfg.includeForks) continue;
      if (repo.archived && !cfg.includeArchived) continue;
      repos.push(repo);
    }
    if (list.length < 100) break;
  }
}

// --- per repository -----------------------------------------------------------
const out = [];
const status = [];
for (const repo of repos) {
  const fullName = repo.full_name;
  const cacheFile = `github-public-cache__${String(fullName).toLowerCase().replace('/', '__')}.json`;
  const prev = existing[cacheFile];
  const nowIso = new Date().toISOString();

  // 0. Out of quota: stop spending, keep whatever is already cached.
  if (budget !== null && budget <= cfg.rateReserve) {
    status.push({
      cache_file: cacheFile,
      full_name: fullName,
      collection: 'deferred',
      refreshed_at_utc: nowIso,
      data_changed_at_utc: prev ? prev.data_changed_at_utc || prev.refreshed_at_utc : null,
      commit_count: prev ? prev.commit_count : 0,
      source_state: prev ? prev.source_state : 'error',
      source_error: 'deferred: rate-limit reserve reached, cache left untouched',
    });
    continue;
  }

  const reuse = () =>
    prev &&
    prev.repository_id === repo.id &&
    prev.history === cfg.history &&
    prev.default_branch === repo.default_branch &&
    prev.pushed_at_utc === repo.pushed_at &&
    !cfg.forceFull;

  // 1. Unchanged since the cached copy: fetch nothing at all.
  if (reuse() && !prev.source_error) {
    // Emit nothing: the data file is already correct, so it is not rewritten. Only the
    // small status file records that this repository was checked.
    status.push({
      cache_file: cacheFile,
      full_name: fullName,
      collection: 'skipped',
      refreshed_at_utc: nowIso,
      data_changed_at_utc: prev.data_changed_at_utc || prev.refreshed_at_utc,
      commit_count: prev.commit_count,
      source_state: prev.source_state,
      source_error: prev.source_error || null,
    });
    continue;
  }

  let languages = (prev && prev.languages_bytes) || {};
  let commits = [];
  let state = 'complete';
  let error = null;
  let pages = 0;
  let mode = 'full';
  let preserved = false;

  try {
    languages = (await get(`${API}/repos/${fullName}/languages`)) || languages;
  } catch (e) {
    state = 'partial';
    error = `languages: ${e.message}`;
  }

  // Incremental is only valid when the previous copy covers the same history mode.
  const canIncrement =
    prev &&
    !cfg.forceFull &&
    prev.history === cfg.history &&
    Array.isArray(prev.commits) &&
    prev.commits.length > 0;

  try {
    if (canIncrement) {
      mode = 'incremental';
      // Overlap by an hour: author date and committer date can disagree, and a push
      // can land commits slightly out of order. Duplicates are removed by sha below.
      const newest = prev.commits.map((c) => c.committed_at_utc).filter(Boolean).sort().pop();
      const since = new Date(new Date(newest).getTime() - 3600 * 1000).toISOString();
      const fetched = [];
      for (let page = 1; page <= cfg.maxCommitPages; page++) {
        const raw = await get(`${API}/repos/${fullName}/commits`, { per_page: 100, page, since });
        const list = Array.isArray(raw) ? raw : [];
        pages = page;
        fetched.push(...list.filter((c) => c && c.sha));
        if (list.length < 100) break;
      }
      // Rewrite detection: the cached head must still exist upstream. If it does not,
      // history was rewritten and a merge would keep commits GitHub no longer has.
      const cachedHead = prev.commits[0] && prev.commits[0].sha;
      const stillPresent = !cachedHead || fetched.some((c) => c.sha === cachedHead);
      if (!stillPresent) {
        mode = 'full';
        state = 'partial';
        error = 'history rewritten upstream; re-collected in full';
        commits = [];
      } else {
        commits = fetched;
      }
    }

    if (mode === 'full') {
      for (let page = 1; page <= cfg.maxCommitPages; page++) {
        const qs = { per_page: 100, page };
        if (cfg.since) qs.since = cfg.since;
        const raw = await get(`${API}/repos/${fullName}/commits`, qs);
        const list = Array.isArray(raw) ? raw : [];
        pages = page;
        commits.push(...list.filter((c) => c && c.sha));
        if (list.length < 100) break;
        if (page === cfg.maxCommitPages) {
          state = 'partial';
          error = `commits: capped at ${cfg.maxCommitPages} pages (${commits.length} commits)`;
        }
      }
    }
  } catch (e) {
    const empty = /empty/i.test(String(e.message || ''));
    state = empty ? 'empty' : 'error';
    error = `commits: ${e.message}`;
    commits = [];
    // Preserve last-known-good: a failed fetch must never replace real history with
    // an empty list. The record is marked stale and the file is left on disk as-is.
    if (prev && Array.isArray(prev.commits) && prev.commits.length) {
      preserved = true;
      state = 'stale';
    }
  }

  const shape = (c) => ({
    sha: c.sha,
    html_url: c.html_url,
    message: (c.commit && c.commit.message ? c.commit.message : '').split('\n')[0],
    author: {
      login: c.author ? c.author.login : null,
      name: c.commit && c.commit.author ? c.commit.author.name : null,
      email: c.commit && c.commit.author ? c.commit.author.email : null,
    },
    authored_at_utc: c.commit && c.commit.author ? c.commit.author.date : null,
    committed_at_utc: c.commit && c.commit.committer ? c.commit.committer.date : null,
  });

  // Merge: incremental results join the cached history, deduped by sha, newest first.
  let detail;
  if (mode === 'incremental' && prev && !error) {
    const bySha = new Map();
    for (const c of prev.commits) bySha.set(c.sha, c);
    for (const c of commits) bySha.set(c.sha, shape(c));
    detail = [...bySha.values()].sort((a, b) =>
      String(b.committed_at_utc || '').localeCompare(String(a.committed_at_utc || '')),
    );
  } else {
    detail = commits.map(shape);
  }

  const authored = detail.map((c) => c.authored_at_utc).filter(Boolean).sort();
  const periodStart = authored.length ? authored[0] : (prev && prev.period_start_utc) || cfg.since;

  if (preserved) {
    status.push({
      cache_file: cacheFile,
      full_name: fullName,
      collection: 'stale',
      refreshed_at_utc: nowIso,
      data_changed_at_utc: prev.data_changed_at_utc || prev.refreshed_at_utc,
      commit_count: prev.commit_count,
      source_state: state,
      source_error: error,
    });
    continue;
  }

  out.push({
    json: {
      repository_id: repo.id,
      full_name: fullName,
      visibility: repo.visibility,
      default_branch: repo.default_branch,
      description: repo.description || null,
      is_fork: !!repo.fork,
      is_archived: !!repo.archived,
      html_url: repo.html_url,
      pushed_at_utc: repo.pushed_at,
      languages_bytes: languages,
      history: cfg.history,
      period_start_utc: periodStart,
      period_end_utc: cfg.until,
      commit_pages_fetched: pages,
      commit_count: detail.length,
      commit_count_definition:
        'Commits returned by the GitHub REST commits endpoint for the default branch, newest first; not an authored-contribution count.',
      collection: mode,
      source_state: state,
      source_error: error,
      refreshed_at_utc: nowIso,
      data_changed_at_utc: nowIso,
      cache_file: cacheFile,
      commits: detail,
    },
  });

  status.push({
    cache_file: cacheFile,
    full_name: fullName,
    collection: mode,
    refreshed_at_utc: nowIso,
    data_changed_at_utc: nowIso,
    commit_count: detail.length,
    source_state: state,
    source_error: error,
  });
}

// One small file per run: which repositories were checked and when. Written every run so
// the "last checked" signal survives without rewriting multi-hundred-kilobyte payloads.
out.push({
  json: {
    generated_at_utc: new Date().toISOString(),
    owners: cfg.owners,
    history: cfg.history,
    repository_count: status.length,
    repositories: status.sort((a, b) => a.cache_file.localeCompare(b.cache_file)),
    cache_file: STATUS_FILE,
  },
});

return out;
